mapper.select:
/* 1. 리뷰 신고 요약 (그룹화 적용) */ SELECT r.`target_type` AS `targetType`, r.`target_id` AS `targetId`, COUNT(r.`id`) AS `reportCount`, MAX(r.`created_at`) AS `lastReportedAt`, IFNULL(rev.`content`, '(삭제된 리뷰입니다)') AS `originalContent`, IFNULL(rev.`user_email`, '삭제된 사용자') AS `authorEmail`, rev.`created_at` AS `originalCreatedAt`, 'REVIEW' AS `category`, MAX(r.`reason_code`) AS `reasonCode` FROM `cors`.`review_reports` AS r LEFT JOIN `cors`.`item_reviews` AS rev ON r.`target_id` = rev.`id` WHERE r.`status` = 'PENDING' AND r.`target_type` = 'REVIEW' GROUP BY r.`target_id`
UNION ALL
/* 2. 댓글 신고 요약 (그룹화 적용) */ SELECT r.`target_type` AS `targetType`, r.`target_id` AS `targetId`, COUNT(r.`id`) AS `reportCount`, MAX(r.`created_at`) AS `lastReportedAt`, IFNULL(cmt.`content`, '(삭제된 댓글입니다)') AS `originalContent`, IFNULL(cmt.`user_email`, '삭제된 사용자') AS `authorEmail`, cmt.`created_at` AS `originalCreatedAt`, 'COMMENT' AS `category`, MAX(r.`reason_code`) AS `reasonCode` FROM `cors`.`review_reports` AS r LEFT JOIN `cors`.`item_review_comments` AS cmt ON r.`target_id` = cmt.`id` WHERE r.`status` = 'PENDING' AND r.`target_type` = 'COMMENT' GROUP BY r.`target_id`
ORDER BY `reportCount` DESC, `lastReportedAt` DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE `cors`.`review_reports`
SET `status` = #{status},
    `updated_at` = NOW()
WHERE `target_type` = #{targetType}
  AND `target_id` = #{targetId}
  AND `status` = 'PENDING'
